def solution(s):
    import math

    n, m = map(int, s.strip().split())

    if n == 1 or m == 1:
        return "0\n"

    total = n * m

    # For large boards (both dimensions >= 3), we can generally pair all but possibly 2 cells
    if n >= 3 and m >= 3:
        if total % 2 == 0:
            result = total - 2
        else:
            result = total - 1
        return str(result) + "\n"

    # Special cases for small boards
    if n == 2:
        # For 2×m boards, analyze by cases
        if m == 2:
            return "0\n"
        elif m == 3:
            return "8\n"
        else:
            # For 2×m where m > 3
            if m % 2 == 0:
                return str(2 * m - 2) + "\n"
            else:
                return str(2 * m - 1) + "\n"

    if m == 2:
        # For n×2 boards
        if n == 2:
            return "0\n"
        elif n == 3:
            return "8\n"
        else:
            # For n×2 where n > 3
            if n % 2 == 0:
                return str(2 * n - 2) + "\n"
            else:
                return str(2 * n - 1) + "\n"

    return str(total - 2) + "\n"

