def get_divisors(n):
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
        i += 1
    return sorted(divisors)

def factorize(n):
    """Get all prime factors with multiplicities"""
    pf = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            pf.append(d)
            temp //= d
        d += 1
    if temp > 1:
        pf.append(temp)
    return pf

