def permute_items(items, max_length):
    """Generate permutations up to certain length"""
    from itertools import permutations
    for r in range(1, min(len(items) + 1, max_length + 1)):
        for perm in permutations(items[:r]):
            yield list(perm)

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    ops = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # ans[j] = earliest time step to get exactly j bananas (1-indexed)
    ans = [-1] * (m + 1)

    # reachable = set of values we can have after current time step
    reachable = {0}

    for step, (t, x, y) in enumerate(ops, 1):
        new_reachable = set()

        if t == 1:
            # Type 1: k := ceil(k + x)
            for v in reachable:
                if v > m:
                    continue
                cur = v
                marked = False
                # Try applying 0 to y times
                for repeat in range(y + 1):
                    if cur > m:
                        break
                    if not marked:
                        new_reachable.add(cur)
                        if ans[cur] == -1:
                            ans[cur] = step
                            marked = True
                    # Apply operation if we're going to next iteration
                    if repeat < y:
                        cur = math.ceil(cur + x)
        else:
            # Type 2: k := ceil(k * x)
            for v in reachable:
                if v > m:
                    continue
                cur = v
                marked = False
                # Try applying 0 to y times
                for repeat in range(y + 1):
                    if cur > m:
                        break
                    if not marked:
                        new_reachable.add(cur)
                        if ans[cur] == -1:
                            ans[cur] = step
                            marked = True
                    # Apply operation if we're going to next iteration
                    if repeat < y:
                        cur = math.ceil(cur * x)

        reachable.update(new_reachable)
        # Clean up: remove values > m to limit set size
        reachable &= {v for v in reachable if v <= m}

    # Output ans[1] to ans[m] as space-separated string
    result = [str(ans[i]) for i in range(1, m + 1)]
    return ' '.join(result) + ' '

