            if level[v] == -1:
                level[v] = level[u] + 1
                queue.append(v)

    # For each edge, direct based on level positions
    result = []
    for a, b, c in edges:
        if level[a] < level[b]:
            result.append(0)  # a -> b
        elif level[b] < level[a]:
            result.append(1)  # b -> a
