def solution(input_str):
    # Parse input
    try:
        parts = input_str.strip().split()
        l = int(parts[0])
        r = int(parts[1])
    except:
        return "0\n"

    def power(a, b, m):
        """Computes (a^b) % m efficiently"""
        res = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                res = (res * a) % m
            a = (a * a) % m
            b //= 2
        return res

    def is_prime(n):
        """Miller-Rabin primality test"""
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0:
            return False

        # Write n-1 as 2^r * d
        r = 0
        d = n - 1
        while d % 2 == 0:
            r += 1
            d //= 2

        # Test against several bases
        for _ in range(5):  # 5 iterations for good accuracy
            a = random.randint(2, min(n - 2, 2**30))
            if a >= n - 2:
                a = n - 3

            x = power(a, d, n)
            if x == 1 or x == n - 1:
                continue

            for _ in range(r - 1):
                x = (x * x) % n
                if x == n - 1:
                    break
            else:
                return False

        return True

    count = 0
    for i in range(l, r + 1):
        if is_prime(i) and (i == 2 or i % 4 == 1):
            count += 1

    return f"{count}\n"

