        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    # Process edges
    idx = 1
    for i in range(m):
        if idx >= len(lines):
            break
        parts = lines[idx].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            union(u, v)
        idx += 1

    # Count size of each component
    comp_size = {}
    for i in range(1, n + 1):
        root = find(i)
        comp_size[root] = comp_size.get(root, 0) + 1

    sizes = sorted(comp_size.values(), reverse=True)

    # Generate lucky numbers up to n
    lucky = []
    def dfs(current):
        if current == 0:
            return
        if current <= n:
            lucky.append(current)
        if current * 10 + 4 <= n:
            dfs(current * 10 + 4)
        if current * 10 + 7 <= n:
            dfs(current * 10 + 7)

    dfs(0)
    lucky.sort()

    # Check if any existing component is lucky
    if any(s in lucky_set := set(lucky) for s in sizes):
        return "0\n"

    # DP: dp[sum] = minimum components needed to reach exactly this sum
    # Using a list for better performance when sums are dense
    max_sum = n + 1
