    dp[0] = 0

    for size in sizes:
        # Build new_dp to store updates
        changes = {}
        for s in range((max_sum - 1) - size, -1, -1):
            if dp[s] != INF:
                new_s = s + size
                new_c = dp[s] + 1
                if new_c < changes.get(new_s, INF):
                    changes[new_s] = new_c

        # Apply changes
        for s, c in changes.items():
            if c < dp[s]:
                dp[s] = c

    # Find minimum roads for any lucky size
    min_roads = INF
    for target in lucky:
        if dp[target] < INF:
            min_roads = min(min_roads, dp[target] - 1)

    if min_roads == INF:
        return "-1\n"
    else:
