def is_gp(seq):
    """Check if a sequence is a geometric progression"""
    n = len(seq)
    if n <= 1:
        return True

    # All zeros is a valid GP
    if all(x == 0 for x in seq):
        return True

    # If first element is 0, all elements must be 0
    if seq[0] == 0:
        return False

    # Since seq[0] != 0, any zero elsewhere makes it invalid
    for x in seq:
        if x == 0:
            return False

    # Check constant ratio using cross multiplication to avoid floating point issues
    # If seq[i+1]/seq[i] = seq[1]/seq[0], then seq[i+1]*seq[0] = seq[i]*seq[1]
    for i in range(1, n - 1):
        if seq[i + 1] * seq[0] != seq[i] * seq[1]:
            return False

    return True


