def is_diamond_square(grid, r, c, k, n, m):
    """Check if there's a diamond square with Manhattan radius k centered at (r, c)."""

    # Check perimeter (Manhattan distance == k) are all 1
    perimeter_ok = True
    for i in range(n):
        for j in range(m):
            if abs(i - r) + abs(j - c) == k:
                if grid[i][j] != '1':
                    perimeter_ok = False
                    break
        if not perimeter_ok:
            break

    if not perimeter_ok:
        return False

    # Check interior (Manhattan distance < k) are all 0
    interior_ok = True
    for i in range(n):
        for j in range(m):
            if abs(i - r) + abs(j - c) < k:
                if grid[i][j] != '0':
                    interior_ok = False
                    break
        if not interior_ok:
            break

    if not interior_ok:
        return False

    # Check no foreign 1 touches the diamond
    # Check all cells in the perimeter's surrounding ring
    for i in range(max(0, r - 2), min(n, r + k + 2)):
        for j in range(max(0, c - 2), min(m, c + k + 2)):
            if abs(i - r) + abs(j - c) == k:  # On perimeter
                continue
            if grid[i][j] != '0' or grid[i][j] == '1':
                # Check if this 1 is touching the perimeter
                for pi in range(max(0, i - 1), min(n, i + 2)):
                    for pj in range(max(0, j - 1), min(m, j + 2)):
                        if abs(pi - r) + abs(pj - c) == k:
                            # Touching!
                            return False

    return True

