MOD = 10**9 + 7

class Parser:
    def __init__(self, s):
        self.s = s.strip()
        self.pos = 0
        self.slen = len(self.s)

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        result = self.parse_term()

        while self.pos < self.slen and self.s[self.pos] == '+':
            self.pos += 1
            term = self.parse_term()
            result = (result + term) % MOD

        return result

    def parse_term(self):
        num_str = self.parse_number()
        l = int(num_str)

        if self.pos < self.slen and self.s[self.pos] == '-':
            self.pos += 1
            r = self.parse_number()
            return concat_range(l, r)

        if self.pos < self.slen and self.s[self.pos] == '(':
            self.pos += 1
            inner = self.parse_expression()
            if self.pos < self.slen and self.s[self.pos] == ')':
                self.pos += 1
            return concat_repeated(inner, l)

        return l

    def parse_number(self):
        start = self.pos
        while self.pos < self.slen and self.s[self.pos].isdigit():
            self.pos += 1
        return self.s[start:self.pos]

def concat_range(l, r):
    s = ''.join(str(i) for i in range(l, r + 1))
    return int(s) % MOD

def concat_repeated(inner, count):
    if hasattr(inner, 'value'):
        n = inner.value
    else:
        n = inner
    s = str(n) * count
    return int(s) % MOD

