import sys

def solution(input_string):
    lines = input_string.strip().split('\n')

    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0'

    dist = {}

    # Precompute the minimum x for efficiency
    min_x = min(x)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    # BFS to find minimum moves
    queue = deque([(a, 0)])
    dist[a] = 0

    while queue:
        curr, steps = queue.popleft()

        if curr == b:
            return str(steps)

        # Find minimum remainder that we can achieve
        # We want to subtract as much as possible

        # Option 1: Subtract 1
        if curr - 1 >= b:
            if curr - 1 not in dist:
                dist[curr - 1] = steps + 1
                queue.append((curr - 1, steps + 1))

        # Option 2: Subtract (curr mod xi) for each xi
        # To optimize, we only need to try each xi once
        for xi in x:
            rem = curr % xi
            if rem > 0:
                new_val = curr - rem
                if new_val >= b and new_val not in dist:
                    dist[new_val] = steps + 1
                    queue.append((new_val, steps + 1))

    return str(dist.get(b, curr + (curr - b)))

# Additional optimization with visited array
def solution_optimized(input_string):
    lines = input_string.strip().split('\n')

    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0'

    # Use an array for distance tracking since we know the range is [b, a]
    range_size = a - b + 1
    dist = [-1] * range_size
    offset = b

    dist[a - b] = 0
    queue = deque([a - b])

    # Precompute for quick modular arithmetic
    # Sort x values to try larger moduli first for bigger jumps
    x.sort(reverse=True)

    while queue:
        curr = queue.popleft()
        curr_val = curr + offset

        if curr_val == b:
            return dist[curr]

        # Try all possible moves
        moves = [curr - 1] + [curr - (curr_val % xi) for xi in x]

        for next_val in moves:
            if next_val >= b and next_val <= a:
                next_idx = next_val - offset
                if dist[next_idx] == -1:
                    dist[next_idx] = dist[curr] + 1
                    queue.append(next_idx)

    return str(dist[b - offset])

from functools import lru_cache

def solution(input_str):
    a, b, n = map(int, input_str.split())

    @lru_cache(maxsize=None)
    def can_win(current_a, current_b):
        """Return True if the current player can force a win from position (current_a, current_b)"""
        if current_a ** current_b >= n:
            return False  # Current player already loses (previous player forced them here)

        can_force_loss = False

        # Move 1: Add box (increase a)
        new_a = current_a + 1
        new_b = current_b
        if new_a ** new_b < n:
            if not can_win(new_a, new_b):
                can_force_loss = True

        # Move 2: Add item (increase b)
        if not can_force_loss:
            new_a = current_a
            new_b = current_b + 1
            if new_a ** new_b < n:
                if not can_win(new_a, new_b):
                    can_force_loss = True

        return can_force_loss

    # If Stas can win from initial position, then Masha loses
    if can_win(a, b):
        return "Masha"
    else:
        return "Stas"

