        next_move = []
        for i in range(n):
            next_move.append(lines[idx])
            idx += 1

        visited = [[0] * m for _ in range(n)]

        def get_next_r_c(r, c):
            d = next_move[r][c]
            if d == 'U':
                return r - 1, c
            elif d == 'D':
                return r + 1, c
            elif d == 'L':
                return r, c - 1
            elif d == 'R':
                return r, c + 1

        comp_id = 1
        comp_nodes = {}
        comp_zeros = {}

        for r in range(n):
            for c in range(m):
                if visited[r][c] == 0:
                    comp_id += 1
                    comp_nodes[comp_id] = 0
                    comp_zeros[comp_id] = 0
                    stack = [(r, c)]
                    visited[r][c] = comp_id

                    while stack:
                        cr, cc = stack.pop()
                        comp_nodes[comp_id] += 1
                        if grid[cr][cc] == '0':
                            comp_zeros[comp_id] += 1

                        nr, nc = get_next_r_c(cr, cc)
                        visited[nr][nc] = comp_id
                        stack.append((nr, nc))

