def solution(input_str):
    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append([x, y])

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def is_valid_triangle(i, k, j):
        # Check if triangle (i, k, j) is non-degenerate
        cp = cross_product(points[i], points[k], points[j])
        return cp != 0

    # dp[i][j] = number of triangulations for polygon segment from vertex i to j (indices 1 to n)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: adjacent vertices have 1 way
    for i in range(1, n + 1):
        dp[i][i + 1] = 1

    # Build DP for increasing lengths
    for length in range(2, n):
        for i in range(1, n - length + 2):
            j = i + length
            dp[i][j] = 0
            for k in range(i + 1, j):
                if is_valid_triangle(i, k, j):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    # Count triangulations using vertex 0 as reference
    # For polygon, we check all diagonals from vertex 1 and count valid triangulations
    ans = 0
    for k in range(2, n + 1):
        cp = cross_product(points[0], points[k], points[1])
        if cp != 0:
            # Triangle (0, 1, k) is valid
            # Multiply dp[0][k] and dp[k][1]
            ans = (ans + dp[0][k] * dp[k][1]) % MOD

    return str(ans)

