    # Target position for leftmost pollywog
    target = n - x + 1

    if target <= 1:
        return '0\n'

    @lru_cache(maxsize=None)
    def dp(pos):
        # Already at target position
        if pos >= target:
            return 0

        ans = float('inf')

        for d in range(1, k + 1):
            # Can only jump if distance >= x (to avoid landing on occupied stones)
            if d < x:
                continue

            new_pos = pos + d

            # Only process valid paths (don't overshoot unnecessarily)
            if new_pos > target:
                continue

            # Calculate cost
            cost = c[d - 1]
            if new_pos in special:
                cost += special[new_pos]

            ans = min(ans, cost + dp(new_pos))

        return ans

    result = dp(1)
    return f'{result}\n'

