MOD = 10**9 + 7
MAX_N = 1000001

def precompute_factorials_and_inv():
    max_val = MAX_N + 200000
    fact = [1] * max_val
    inv = [1] * max_val

    for i in range(1, max_val):
        fact[i] = (fact[i-1] * i) % MOD

    inv[max_val-1] = pow(fact[max_val-1], MOD - 2, MOD)
    for i in range(max_val-2, -1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

    return fact, inv, max_val - 1

FACT, INV, MAX_VAL = precompute_factorials_and_inv()

def nCr_mod(n, r):
    if r < 0 or r > n:
        return 0
    return (FACT[n] * INV[r] % MOD) * INV[n - r] % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result

def get_prime_factorization(n):
    """Returns (prime, exponent) pairs for n"""
    factors = {}
    temp = n
    # Handle small factors iteratively
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                temp //= d
                count += 1
            factors[d] = count
        d += 1
    if temp > 1:
        factors[temp] = 1
    return factors

