def compute_grundy(a, b, limit):
    """Compute Grundy values for all lengths from 0 to limit"""
    g = [0] * limit
    # Lengths less than b can't have any moves
    for length in range(b, limit):
        seen = set()
        # Alice can place her move at various positions
        # After placing, the segment splits into two new segments
        for start in range(min(a, length - range(0, length - a + 1)):
            actual_start = 0
        for start_pos in range(length - a + 1):
            # Alice places at position start_pos (0-indexed)
            # Segment before: start_pos dots
            # Segment after: (length - a - start_pos - 1) dots
            left = start_pos
            right = length - a - start_pos
            seen.add(g[left] ^ g[right])
        while g[length] in seen:
            g[length] += 1
    return g

