def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    pos = {x: i for i, x in enumerate(p)}
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Union elements if a-x or b-x exists
    for i in range(n):
        x = p[i]
        if (a - x) in pos and (a - x) != x:
            union(i, pos[a - x])
        if (b - x) in pos and (b - x) != x:
            union(i, pos[b - x])

    # Group elements by their component root
    root_to_members = {}
    for i in range(n):
        r = find(i)
        if r not in root_to_members:
            root_to_members[r] = []
        root_to_members[r].append(i)

    # Check each component
    valid = True
    assigned = [0] * n

    for r in root_to_members:
        members = root_to_members[r]
        can_be_a = True
        can_be_b = True

        for idx in members:
            x = p[idx]

            # Check if complement for set A exists
            comp_a = a - x
            if comp_a != x and comp_a in pos:
                comp_idx = pos[comp_a]
                if find(idx) != find(comp_idx):
                    can_be_a = False
                    break

            # Check if complement for set B exists
            comp_b = b - x
            if comp_b != x and comp_b in pos:
                comp_idx = pos[comp_b]
                if find(idx) != find(comp_idx):
                    can_be_b = False
                    break

        if not (can_be_a or can_be_b):
            valid = False
            break

        # Assign this component to a set
        if can_be_a:
            for idx in members:
                assigned[idx] = 0
        else:
            for idx in members:
                assigned[idx] = 1

    if valid:
        return 'YES\n' + ' '.join(map(str, assigned))
    else:
        return "NO"


