                candidate = "".join(pre) + substr + "".join(post)
                if candidate and candidate[0] != '0':
                    if best_n is None or candidate < best_n:
                        best_n = candidate
        else:
            # No non-zero digits available
            if substr[0] == '0' and len(substr) > 1:
                # Substring starts with '0', must ensure no leading zero
                if "".join(remaining)[:1] != '0' if remaining else False:
                    pass
                continue

            if substr and substr[0] != '0':
                candidate = substr + "".join(pre) + "".join(post)
                if candidate[0] != '0':
                    if best_n is None or candidate < best_n:
                        best_n = candidate
            else:
                candidate = "".join(pre) + substr + "".join(post)
                if candidate and candidate[0] != '0':
                    if best_n is None or candidate < best_n:
                        best_n = candidate

        if best_n is None and first_nonzero is not None:
            # Try with first_nonzero prepended
            candidate = first_nonzero + substr + "".join(remaining)
            if candidate and candidate[0] != '0':
                if best_n is None or candidate < best_n:
                    best_n = candidate

    # Handle edge case where we need to find minimum
    if best_n is None and first_nonzero and len(remaining) > 0 and substr in "".join(remaining):
        candidate = first_nonzero + "".join(remaining)
        if candidate[0] != '0':
