    elif best_n is None and first_nonzero:
        candidate = first_nonzero + "".join(remaining) + substr
        if candidate and candidate[0] != '0':
            best_n = candidate

    if best_n is None and substr == "0":
        return "0"

    # If no valid n found with first_nonzero, try without
    if best_n is None and remaining:
        best_n = "".join(remaining) + substr
        if best_n and best_n[0] != '0':
            pass
        elif substr[0] != '0':
